private lemma localMixerScalar_pow_even (β : ℝ) (n : ℕ) :
    ((((-β : ℝ) * Complex.I : ℂ)) ^ (2 * n)) =
      ((-1 : ℂ) ^ n) * ((β : ℂ) ^ (2 * n))

private lemma localMixerScalar_pow_odd (β : ℝ) (n : ℕ) :
    ((((-β : ℝ) * Complex.I : ℂ)) ^ (2 * n + 1)) =
      (((-1 : ℂ) ^ n) * ((β : ℂ) ^ (2 * n + 1))) * (-Complex.I)

private lemma exp_localPauliX_aux (N : ℕ) (β : ℝ) (j : Fin N) :
    NormedSpace.exp ((((-β : ℝ) * Complex.I : ℂ)) • Qubits.localPauliX j) =
      localMixerFactor N β j

@[simp]
theorem isingChainCostUnitary_eq_costExponential {n : ℕ}
    {J : IsingModel.IsingChainCouplings n}
    (hChain : IsingChainQAOAExponentials n J) (γ : ℝ) :
    (hChain.costUnitary γ : Qubits.NQubitOp n) =
      costExponential (isingChainCostHamiltonian J) γ

@[simp]
theorem isingChainMixerUnitary_eq_mixerExponential {n : ℕ}
    {J : IsingModel.IsingChainCouplings n}
    (hChain : IsingChainQAOAExponentials n J) (β : ℝ) :
    (hChain.mixerUnitary β : Qubits.NQubitOp n) =
      mixerExponential (isingChainMixerHamiltonian n) β

@[simp]
theorem isingChainToQAOAExponentials_costHamiltonian_isingChain {n : ℕ}
    {J : IsingModel.IsingChainCouplings n}
    (hChain : IsingChainQAOAExponentials n J) :
    (isingChainToQAOAExponentials hChain).costHamiltonian = isingChainCostHamiltonian J

@[simp]
theorem isingChainToQAOAExponentials_mixerHamiltonian_isingChain {n : ℕ}
    {J : IsingModel.IsingChainCouplings n}
    (hChain : IsingChainQAOAExponentials n J) :
    (isingChainToQAOAExponentials hChain).mixerHamiltonian = isingChainMixerHamiltonian n

@[simp]
theorem isingChainExponentialQAOAState_zero {n : ℕ}
    {J : IsingModel.IsingChainCouplings n}
    (hChain : IsingChainQAOAExponentials n J) (ψ0 : Qubits.NQubitNormKet n) :
    isingChainExponentialQAOAState (n := n) (p := 0) hChain
      (fun i => nomatch i) (fun i => nomatch i) ψ0 = ψ0

private theorem localPauliX_localPauliY_anticomm_at {N : ℕ} (j : Fin N) :
    Qubits.localPauliX j * Qubits.localPauliY j =
      -(Qubits.localPauliY j * Qubits.localPauliX j)

private theorem localPauliX_localPauliZ_anticomm_at {N : ℕ} (j : Fin N) :
    Qubits.localPauliX j * Qubits.localPauliZ j =
      -(Qubits.localPauliZ j * Qubits.localPauliX j)

private lemma nextSite_castSucc {P : ℕ} (k : Fin (2*P+1)) :
    IsingModel.nextSite (k.castSucc : Fin (2*P+2)) =
      (k.succ : Fin (2*P+2))

private lemma nextSite_last (P : ℕ) :
    IsingModel.nextSite (Fin.last (2*P+1) : Fin (2*P+2)) =
      (0 : Fin (2*P+2))

private lemma spinValue_mul_spinValue (b₁ b₂ : Fin 2) :
    IsingModel.spinValue b₁ * IsingModel.spinValue b₂ =
      if b₁ = b₂ then (1 : ℝ) else (-1 : ℝ)

private lemma boundaryTerm_eq (P : ℕ) (z : Qubits.BitString (2*P+2)) :
    -(IsingModel.classicalSpin z (Fin.last (2*P+1) : Fin (2*P+2)) *
        IsingModel.classicalSpin z (0 : Fin (2*P+2))) - 1 =
      if z (Fin.last (2*P+1) : Fin (2*P+2)) = z (0 : Fin (2*P+2))
        then (-2 : ℝ) else (0 : ℝ)

private lemma alternatingBitString_body_disagree (P : ℕ) (k : Fin (2*P+1)) :
    (alternatingBitString (2*P+2)) (k.castSucc : Fin (2*P+2)) ≠
      (alternatingBitString (2*P+2)) (k.succ : Fin (2*P+2))

private lemma alternatingBitString_boundary_disagree (P : ℕ) :
    (alternatingBitString (2*P+2)) (Fin.last (2*P+1) : Fin (2*P+2)) ≠
      (alternatingBitString (2*P+2)) (0 : Fin (2*P+2))

private lemma Hred_z_pm_plus_NR_eigenvalue_lower_bound (P : ℕ)
    (z : Qubits.BitString (2*P+2)) :
    -(2*P : ℝ) ≤ eigenvalueOnBasis P z + (2*P+2 : ℝ)

private lemma conj_sum_distrib {N : ℕ} {ι : Type*} (s : Finset ι)
    (U : Qubits.NQubitOp N) (A : ι → Qubits.NQubitOp N) :
    U† * (∑ k ∈ s, A k) * U = ∑ k ∈ s, U† * A k * U

private lemma conj_one {N : ℕ} (U : Qubits.NQubitUnitaryOp N) :
    (U : Qubits.NQubitOp N)† * (1 : Qubits.NQubitOp N) *
        (U : Qubits.NQubitOp N) = (1 : Qubits.NQubitOp N)

private lemma conj_sub {N : ℕ} (U : Qubits.NQubitOp N)
    (A B : Qubits.NQubitOp N) :
    U† * (A - B) * U = U† * A * U - U† * B * U

private lemma conj_smul {N : ℕ} (U : Qubits.NQubitOp N) (c : ℂ)
    (A : Qubits.NQubitOp N) :
    U† * (c • A) * U = c • (U† * A * U)

private lemma conj_add {N : ℕ} (U : Qubits.NQubitOp N)
    (A B : Qubits.NQubitOp N) :
    U† * (A + B) * U = U† * A * U + U† * B * U

@[simp]
private theorem nextSiteEquiv_apply (P : ℕ) (j : Fin (2*P+2)) :
    nextSiteEquiv P j = IsingModel.nextSite j

private lemma Hred_z_pm_false_add_NR_eq_S_pbc (P : ℕ) :
    Hred_z_pm false P + ((2*P+2 : ℕ) : ℂ) • (1 : Qubits.NQubitOp (2*P+2)) =
      S_pbc P

private lemma orbit_zero_val (P : ℕ) :
    ∀ k : ℕ, k < 2*P+2 →
      (((nextSiteEquiv P)^k) (0 : Fin (2*P+2))).val = k

@[simp]
private lemma orbitFromZeroEquiv_apply (P : ℕ) (n : Fin (2*P+2)) :
    (orbitFromZeroEquiv P) n = ((nextSiteEquiv P)^n.val) (0 : Fin (2*P+2))

theorem residualEnergy_attained {N P : ℕ}
    (hN_even : 2 ∣ N) (hP : 2 * P + 2 ≤ N) :
    ∃ γ β : Fin P → ℝ, residualEnergy (ringQAOA N) γ β = 1 / (2 * P + 2)

theorem residualEnergy_isLeast {N P : ℕ}
    (hN_even : 2 ∣ N) (hP : 2 * P + 2 ≤ N) :
    IsLeast {e | ∃ γ β : Fin P → ℝ, residualEnergy (ringQAOA N) γ β = e}
      (1 / (2 * P + 2))

private lemma reflect_multiset_prod_X_sub_C (S : Multiset ℂ) (h0 : (0 : ℂ) ∉ S) :
    Polynomial.reflect S.card ((S.map (fun ζ => X - Polynomial.C ζ)).prod)
      = (S.map (fun ζ => Polynomial.C (-ζ) * (X - Polynomial.C ζ⁻¹))).prod

private lemma map_conj_prod_X_sub_C (S : Multiset ℂ) :
    ((S.map (fun ζ => X - Polynomial.C ζ)).prod).map (starRingEnd ℂ)
      = ((S.map (starRingEnd ℂ)).map (fun ζ => X - Polynomial.C ζ)).prod

private lemma prod_eq_one_of_invclosed_no_fixed (S : Multiset ℂ)
    (h0 : (0 : ℂ) ∉ S) (hinv : S.map (·⁻¹) = S) (hnf : ∀ ζ ∈ S, ζ⁻¹ ≠ ζ) :
    S.prod = 1

theorem Tpoly_abs_circle_lt_one (P : ℕ) {θ : ℝ}
