      = Polynomial.C (1/4 : ℂ)

@[simp] theorem windowDataEquiv_apply {N m : ℕ} {S : Finset (Fin N)}
    (ε : Fin m ≃ S) (a : Fin (Qubits.NQubitDim m)) :
    windowDataEquiv ε a = windowData ε a

theorem extendByZeroOnS_restrict_agree_on_S {N : ℕ} {S T : Finset (Fin N)}
    (hST : S ⊆ T) (zs : T → Fin 2) (k : Fin N) (hk : k ∈ S) :
    extendByZeroOnS T zs k = extendByZeroOnS S (restrictData hST zs) k

theorem AgreeOutside.symm {N : ℕ} {S : Finset (Fin N)}
    {z w : Qubits.BitString N} (h : AgreeOutside S z w) :
    AgreeOutside S w z

theorem AgreeOutside.trans {N : ℕ} {S : Finset (Fin N)}
    {x y z : Qubits.BitString N}
    (hxy : AgreeOutside S x y) (hyz : AgreeOutside S y z) :
    AgreeOutside S x z

theorem AgreeOutside.trans_union {N : ℕ} {S T : Finset (Fin N)}
    {x y z : Qubits.BitString N}
    (hxy : AgreeOutside S x y) (hyz : AgreeOutside T y z) :
    AgreeOutside (S ∪ T) x z

theorem supportedOn_smul {N : ℕ} {S : Finset (Fin N)} {O : Qubits.NQubitOp N}
    (c : ℂ) (hO : supportedOn S O) :
    supportedOn S (c • O)

theorem supportedOn_add {N : ℕ} {S T : Finset (Fin N)}
    {O O' : Qubits.NQubitOp N}
    (hO : supportedOn S O) (hO' : supportedOn T O') :
    supportedOn (S ∪ T) (O + O')

theorem supportedOn_mul {N : ℕ} {S T : Finset (Fin N)}
    {O O' : Qubits.NQubitOp N}
    (hO : supportedOn S O) (hO' : supportedOn T O') :
    supportedOn (S ∪ T) (O * O')

private theorem permMatrix_mul_stdKet_full {n : ℕ} (σ : Equiv.Perm (Fin n))
    (i : Fin n) :
    Equiv.Perm.permMatrix ℂ σ * stdKet n i = stdKet n (σ⁻¹ i)

private theorem braket_eq_dotProduct {n : ℕ}
    (ψ : Qubits.NQubitKet n) (O : Qubits.NQubitOp n) :
    ψ.dag * (O * ψ) = dotProduct (star ψ.vec) (Matrix.mulVec O ψ.vec)

theorem tensorSupportedOn_mul_same {N : ℕ} {W : Finset (Fin N)}
    {A B : Qubits.NQubitOp N}
    (hA : tensorSupportedOn W A) (hB : tensorSupportedOn W B) :
    tensorSupportedOn W (A * B)

theorem tensorSupportedOn.toSupportedOn {N : ℕ} {S : Finset (Fin N)}
    {A : Qubits.NQubitOp N} (hA : tensorSupportedOn S A) :
    supportedOn S A

theorem tensorSupportedOn_smul {N : ℕ} {S : Finset (Fin N)} {A : Qubits.NQubitOp N}
    (c : ℂ) (hA : tensorSupportedOn S A) :
    tensorSupportedOn S (c • A)

theorem tensorSupportedOn_add {N : ℕ} {S T : Finset (Fin N)}
    {A B : Qubits.NQubitOp N}
    (hA : tensorSupportedOn S A) (hB : tensorSupportedOn T B) :
    tensorSupportedOn (S ∪ T) (A + B)

private lemma mulMatchBitString_S_eq {N : ℕ} {S T : Finset (Fin N)}
    {ix' iy' iz : Qubits.BitString N} {k : Fin N} (hkS : k ∈ S) (hkT : k ∈ T) :
    mulMatchBitString S T ix' iy' iz k = iz k

private lemma mulMatchBitString_SnotT {N : ℕ} {S T : Finset (Fin N)}
    {ix' iy' iz : Qubits.BitString N} {k : Fin N} (hkS : k ∈ S) (hkT : k ∉ T) :
    mulMatchBitString S T ix' iy' iz k = iy' k

private lemma mulMatchBitString_notS {N : ℕ} {S T : Finset (Fin N)}
    {ix' iy' iz : Qubits.BitString N} {k : Fin N} (hkS : k ∉ S) :
    mulMatchBitString S T ix' iy' iz k = ix' k

theorem tensorSupportedOn_mul {N : ℕ} {S T : Finset (Fin N)}
    {A B : Qubits.NQubitOp N}
    (hA : tensorSupportedOn S A) (hB : tensorSupportedOn T B) :
    tensorSupportedOn (S ∪ T) (A * B)

theorem tensorSupportedOn_commute_of_disjoint {N : ℕ}
    {S T : Finset (Fin N)} {A B : Qubits.NQubitOp N}
    (hA : tensorSupportedOn S A) (hB : tensorSupportedOn T B)
    (hST : Disjoint S T) :
    Commute A B

theorem supportedOn_conj {N : ℕ} {S_U S S_V : Finset (Fin N)}
    {U O V : Qubits.NQubitOp N}
    (hU : supportedOn S_U U) (hO : supportedOn S O) (hV : supportedOn S_V V) :
    supportedOn (S_U ∪ S ∪ S_V) (U * O * V)

private theorem chainPairInteraction_castSucc (P : ℕ) (k : Fin (2 * P + 1)) :
    IsingModel.chainPairInteraction (k.castSucc : Fin (2*P+2)) =
      localPauliZ (k.castSucc : Fin (2*P+2)) * localPauliZ ((k.castSucc : Fin (2*P+2)) + 1)

private theorem chainPairInteraction_last (P : ℕ) :
    IsingModel.chainPairInteraction (Fin.last (2*P+1) : Fin (2*P+2)) =
      localPauliZ (Fin.last (2*P+1)) * localPauliZ (0 : Fin (2*P+2))

private theorem hX_act {N : ℕ} (j : Fin N) :
    ∀ z : BitString N, localPauliX j * computationalBasisKet N z =
      (fun _ : Fin 2 => (1 : ℂ)) (z j) • computationalBasisKet N (flipBitAt z j)

private theorem hY_act {N : ℕ} (j : Fin N) :
    ∀ z : BitString N, localPauliY j * computationalBasisKet N z =
      pauliYPhase (z j) • computationalBasisKet N (flipBitAt z j)

private theorem hZ_act {N : ℕ} (j : Fin N) :
    ∀ z : BitString N, localPauliZ j * computationalBasisKet N z =
      (fun b => Z b b) (z j) • computationalBasisKet N z

theorem car_factor_idem {R : Type*} [Ring R] {a c : R}
    (hself : a * a = 0) (hself' : c * c = 0) (hcar : a * c + c * a = 1) :
    (c * a) * (c * a) = c * a

theorem pairParity_factor_involution {A : Type*} [Ring A] [Algebra ℂ A] {p q : A}
    (hp : p * p = p) (hq : q * q = q) (hpq : Commute p q) :
    ((1 - (2 : ℂ) • p) * (1 - (2 : ℂ) • q)) * ((1 - (2 : ℂ) • p) * (1 - (2 : ℂ) • q)) = 1

theorem combo_not_dvd_of_ne (P : ℕ) (n m : Fin P) (hnm : n ≠ m) {σ τ : ℤ}
